           ],\\n                    [\\n                        1714008120,\\n                        0\\n                    ],\\n                    [\\n                        1714008180,\\n                        0\\n                    ],\\n                    [\\n                        1714008240,\\n                        0\\n                    ],\\n                    [\\n                        1714008300,\\n                        0\\n                    ],\\n                    [\\n                        1714008360,\\n                        0\\n                    ],\\n                    [\\n                        1714008420,\\n                        0\\n                    ],\\n                    [\\n                        1714008480,\\n                        0\\n                    ],\\n                    [\\n                        1714008540,\\n                        0\\n                    ],\\n                    [\\n                        1714008600,\\n                        0\\n                    ],\\n                    [\\n                        1714008660,\\n                        0\\n                    ],\\n                    [\\n                        1714008720,\\n                        0\\n                    ],\\n                    [\\n                        1714008780,\\n                        0\\n                    ],\\n                    [\\n                        1714008840,\\n                        0\\n                    ],\\n                    [\\n                        1714008900,\\n                        0\\n                    ],\\n                    [\\n                        1714008960,\\n                        0\\n                    ],\\n                    [\\n                        1714009020,\\n                        0\\n                    ],\\n                    [\\n                        1714009080,\\n                        0\\n                    ],\\n                    [\\n                        1714009140,\\n                        0\\n                    ],\\n                    [\\n                        1714009200,\\n                        0\\n                    ],\\n                    [\\n                        1714009260,\\n                        0\\n                    ],\\n                    [\\n                        1714009320,\\n                        0\\n                    ],\\n                    [\\n                        1714009380,\\n                        0\\n                    ],\\n                    [\\n                        1714009440,\\n                        0\\n                    ],\\n                    [\\n                        1714009500,\\n                        0\\n                    ],\\n                    [\\n                        1714009560,\\n                        0\\n                    ],\\n                    [\\n                        1714009620,\\n                        0\\n                    ],\\n                    [\\n                        1714009680,\\n                        0\\n                    ],\\n                    [\\n                        1714009740,\\n                        0\\n                    ],\\n                    [\\n                        1714009800,\\n                        0\\n                    ],\\n                    [\\n                        1714009860,\\n                        0\\n                    ],\\n                    [\\n                        1714009920,\\n                        0\\n                    ],\\n                    [\\n                        1714009980,\\n                        0\\n                    ],\\n                    [\\n                        1714010040,\\n                        0\\n                    ],\\n                    [\\n                        1714010100,\\n                        0\\n                    ],\\n                    [\\n                        1714010160,\\n                        0\\n                    ],\\n                    [\\n                        1714010220,\\n                        0\\n                    ],\\n                    [\\n                        1714010280,\\n                        0\\n                    ],\\n                    [\\n                        1714010340,\\n                        0\\n                    ],\\n                    [\\n                        1714010400,\\n                        0\\n                    ],\\n                    [\\n                        1714010460,\\n                        0\\n                    ],\\n                    [\\n                        1714010520,\\n                        0\\n                    ]\\n                ],\\n                \\\"type\\\": \\\"outboundBitsRate\\\"\\n            }\\n        ]\\n    },\\n    \\\"originalUrl\\\": \\\"SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT60S\',\'zero\') AS stat_time, SUM(sent_bytes + received_bytes) AS total_bytes, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_outbound_byte) AS outbound_bytes, SUM(traffic_internal_byte) AS internal_bytes, SUM(traffic_through_byte) AS through_bytes, SUM(sent_pkts + received_pkts) AS total_packets, SUM(traffic_inbound_pkt) AS inbound_packets, SUM(traffic_outbound_pkt) AS outbound_packets, SUM(traffic_internal_pkt) AS internal_packets, SUM(traffic_through_pkt) AS through_packets, SUM(sessions) AS sessions FROM metric_region WHERE stat_time >= toDateTime(1714006946) AND stat_time < toDateTime(1714010546)   AND  side = \'server\' GROUP BY stat_time ORDER BY stat_time ASC\\\",\\n    \\\"msg\\\": \\\"OK\\\"\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/matrix\' as objHandle\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"side\":side,\r\n    \"country\":countryRegion,\r\n    \"province\":superAdminArea\r\n}\r\n\r\npreHandle(parameter);\r\n\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT${step}S\',\'zero\') AS stat_time, SUM(sent_bytes + received_bytes) AS total_bytes, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_outbound_byte) AS outbound_bytes, SUM(traffic_internal_byte) AS internal_bytes, SUM(traffic_through_byte) AS through_bytes, SUM(sent_pkts + received_pkts) AS total_packets, SUM(traffic_inbound_pkt) AS inbound_packets, SUM(traffic_outbound_pkt) AS outbound_packets, SUM(traffic_internal_pkt) AS internal_packets, SUM(traffic_through_pkt) AS through_packets, SUM(sessions) AS sessions FROM metric_region WHERE stat_time >= ${startTime} AND stat_time < ${endTime} <#if country?default(\'\')?trim? length gt 0> AND country_region = \'${country}\' </#if> <#if province?default(\'\')?trim? length gt 0> AND super_admin_area = \'${province}\' </#if> AND  side = \'${side}\' GROUP BY stat_time ORDER BY stat_time ASC\\\",\\\"option\\\":\\\"real_time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"applicationPerformanceLocationThoughput\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = new ArrayList();\r\n\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		for(i,j in list){\r\n			var pojo = list[i];\r\n			var tempObj= {};\r\n			for (key,value in pojo){\r\n				if(key.indexOf(\"total_bytes\") != -1){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"stat_time\") != -1){\r\n					tempObj[\'statTime\'] = pojo[key]\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		var fields = new ArrayList();\r\n		var obj = list[0];\r\n		for(key,value in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			fields.add(key);\r\n		}\r\n\r\n		for(i,j in fields) {\r\n			// 先按照时间排序\r\n			list.sort((a,b)=>a.statTime.asDouble()-b.statTime.asDouble());  \r\n			var key = fields[i];\r\n			var values = new ArrayList();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n\r\n			var sumValue = 0\r\n			for(i,j in list){\r\n				var pojo = list[i];\r\n				var tempArray = new ArrayList();\r\n				tempArray.add(pojo[\"statTime\"]);\r\n				tempArray.add(pojo[key]);\r\n				values.add(tempArray);\r\n				sumValue += pojo[key].asDouble();\r\n			}\r\n\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.type = key;\r\n			o.result.add(lineObj);\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
