tency_avg FROM session_record_cn WHERE recv_time >= toDateTime(1673339501) - 86400 AND recv_time < toDateTime(1673425901) - 86400  AND super_admin_area IN( \'221.7.1.20\',\'221.7.1.21\',\'114.114.114.114\' )   AND (server_super_admin_area=\'xinjing\')  AND decoded_as = \'DNS\' GROUP BY super_admin_area&format=json&option=real_time\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/table\' as objHandle\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult\r\nimport \'@/pre/typeHandle3rd\' as typeHandle3rd\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"type\":type,\r\n    \"params\":params,\r\n    \"q\":q\r\n}\r\n\r\npreHandle(parameter);\r\ntypeHandle3rd(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT ${dimension} AS ${label}, SUM(received_bytes + sent_bytes) AS total_bytes, COUNT(*) AS query_num, ROUND(AVG(dns_response_latency_ms)) AS dns_response_latency_avg FROM session_record_cn WHERE recv_time >= ${startTime} - ${timeDiff} AND recv_time < ${endTime} - ${timeDiff} <#if type?default(\'\')?trim? length gt 0><#if type == \'qtype\' || type == \'rcode\'> AND ${label} IN(<#if params?default(\'\')?trim? length gt 0> ${params} </#if>) <#else> AND ${label} IN(<#if params?default(\'\')?trim? length gt 0> ${params} </#if>) </#if></#if> <#if q?default(\'\')?trim? length gt 0> AND (${q}) </#if><#if filter?default(\'\')?trim? length gt 0> AND ${filter} </#if> AND l7_protocol = \'DNS\' GROUP BY ${label}\\\",\\\"option\\\":\\\"real_time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"dnsOverviewDrilldownDimensionCycleAnalytsis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = postGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = objHandle(galaxyRes);\r\n\r\nreturn result;');
