n\" : [ {\n        \"name\" : \"resultType\",\n        \"value\" : \"table\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"String\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      }, {\n        \"name\" : \"result\",\n        \"value\" : \"\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"Array\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      } ]\n    }, {\n      \"name\" : \"originalUrl\",\n      \"value\" : \"http://192.168.44.55:9999/?query=SELECT super_admin_area, SUM(total_bytes) AS total_bytes, SUM(query_num) AS query_num, SUM(total_internal_query_num) AS total_internal_query_num, SUM(total_external_query_num) AS total_external_query_num, ROUND(AVG(dns_response_latency_avg)) AS dns_response_latency_avg FROM ( SELECT server_super_admin_area AS super_admin_area, SUM(received_bytes + sent_bytes) AS total_bytes, COUNT(*) AS query_num, IF(client_zone = \'internal\', SUM(sessions), 0) AS total_internal_query_num, IF(client_zone = \'external\', SUM(sessions), 0) AS total_external_query_num, ROUND(AVG(dns_response_latency_ms)) AS dns_response_latency_avg FROM session_record_cn WHERE recv_time >= toDateTime(1691559946) AND recv_time < toDateTime(1691563546)  AND notEmpty(super_admin_area)   AND (server_super_admin_area=\'xinjing\')  AND decoded_as = \'DNS\' GROUP BY super_admin_area,client_zone ) GROUP BY super_admin_area  ORDER BY total_bytes desc  LIMIT 10&format=json&option=real_time\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult\r\nimport \'@/pre/typeHandle3rd\' as typeHandle3rd\r\nimport \'@/public/orderHandle\' as orderHandle\r\nimport \'@/public/toHump\' as toHump\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"type\":type,\r\n	\"params\":params,\r\n    \"orderBy\":orderBy,\r\n    \"q\":q\r\n}\r\nparameter.orderBy = orderHandle(parameter.orderBy);\r\npreHandle(parameter);\r\ntypeHandle3rd(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT ${label}, SUM(total_bytes) AS total_bytes, SUM(query_num) AS query_num, SUM(total_internal_query_num) AS total_internal_query_num, SUM(total_external_query_num) AS total_external_query_num, ROUND(AVG(dns_response_latency_avg)) AS dns_response_latency_avg FROM ( SELECT ${dimension} AS ${label}, SUM(received_bytes + sent_bytes) AS total_bytes, COUNT(*) AS query_num, IF(client_zone = \'internal\', SUM(sessions), 0) AS total_internal_query_num, IF(client_zone = \'external\', SUM(sessions), 0) AS total_external_query_num, ROUND(AVG(dns_response_latency_ms)) AS dns_response_latency_avg FROM session_record_cn WHERE recv_time >= ${startTime} AND recv_time < ${endTime} <#if type?default(\'\')?trim? length gt 0 && type!=\'qtype\' && type!=\'rcode\'> AND notEmpty(${label}) </#if><#if params?default(\'\')?trim? length gt 0> AND ${label} IN (${params})</#if> <#if q?default(\'\')?trim? length gt 0> AND (${q}) </#if><#if filter?default(\'\')?trim? length gt 0> AND ${filter} </#if> AND l7_protocol = \'DNS\' GROUP BY ${label},client_zone ) GROUP BY ${label} <#if orderBy?default(\'\')?trim? length gt 0> ORDER BY ${orderBy} desc <#else> ORDER BY query_num desc </#if> LIMIT 10\\\",\\\"option\\\":\\\"real_time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"dnsOverviewDrilldownDimensionAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(i,j in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (key,value in pojo){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key == \'query_num\'){\r\n					tempObj[\'queryRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2);\r\n				}\r\n				if(key == \'total_bytes\'){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8;\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n		}\r\n  	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
