= \'\';\r\n			for (key,value in pojo){    \r\n				val = pojo[key];\r\n			}\r\n			o.result[i] = val;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
