UM(traffic_inbound_byte) AS in_bytes,ROUND(AVG(avg_tcp_rtt_ms), 4) AS establish_latency_ms,ROUND(AVG(avg_http_response_latency_ms), 4) AS http_response_latency,ROUND(AVG(avg_ssl_handshake_latency_ms), 4) AS ssl_con_latency,ROUND(AVG(tcp_lost_bytes_ratio), 4) AS tcp_lostlen_percent,ROUND(AVG(tcp_rtx_pkts_ratio), 4) AS pkt_retrans_percent FROM metric_link WHERE stat_time >= ${startTime} AND stat_time < ${endTime} GROUP BY out_link_id,in_link_id\\\",\\\"option\\\":\\\"real_time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"linkOverviewBigramAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(i,j in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (key,value in pojo){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key == \'out_bytes\'){\r\n					tempObj[\'outBitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8;\r\n				}\r\n				if(key == \'in_bytes\'){\r\n					tempObj[\'inBitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8;\r\n				}\r\n				if(key == \'total_bytes\'){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8;\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
