     \"expression\" : \"\",\n            \"children\" : [ {\n              \"name\" : \"rate\",\n              \"value\" : \"-4703112.0\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"Double\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ ]\n            }, {\n              \"name\" : \"total\",\n              \"value\" : \"-2116401817\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"Integer\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ ]\n            } ]\n          } ]\n        } ]\n      } ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/object\' as objHandle\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult\r\nimport \'@/public/toHump\' as toHump\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"appLabels\":appLabels\r\n}\r\n\r\npreHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT app AS app_label, SUM(sent_bytes + received_bytes) AS bytes_total, SUM(sent_pkts + received_pkts) AS packets_total, SUM(sessions) AS sessions_total FROM metric_application WHERE stat_time >= ${startTime}-${timeDiff} AND stat_time < ${endTime}-${timeDiff} AND app IN (<#if appLabels?default(\\\'\\\')?trim? length gt 0> ${appLabels} </#if>) GROUP BY app_label\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"overviewApplicationCycleTrafficTotal\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new ArrayList();\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		var name = new HashMap();\r\n		for(i,j in list){\r\n			var temp = list[i];\r\n			var tempObj= {};\r\n			for (key,value in temp){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = temp[key];\r\n				if(tempKey == \'appLabel\'){\r\n					name.put(tempObj[tempKey],tempObj[tempKey]);\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		var type = {};\r\n		type.bytes = \'bytesTotal\';\r\n		type.packets = \'packetsTotal\';\r\n		type.sessions = \'sessionsTotal\';\r\n		for(key,value in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			for(i in list){\r\n				for(m,n in i){\r\n					var pojo = {}\r\n					if(m==value){\r\n						pojo.rate=(n.asDouble()/parameter.timeDiff).toFixed(2).asDouble() * 8\r\n						pojo.total=n.asDouble();\r\n                        obj[i[\"appLabel\"]] = pojo;\r\n					}\r\n				}\r\n			}\r\n			old.add(obj);\r\n		}\r\n	}\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}\r\n\r\nreturn result;');
