: false,\n    \"dataType\" : \"Object\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : \"\",\n    \"error\" : \"\",\n    \"expression\" : \"\",\n    \"children\" : [ {\n      \"name\" : \"code\",\n      \"value\" : \"999\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Integer\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"time\",\n      \"value\" : \"2023-01-12 09:51:16\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"message\",\n      \"value\" : \"找不到函数toHump(String) at Row:40~40,Col:19~29\\\\n\\\\n\\\\t\\\\t\\\\t\\\\tvar tempKey = toHump(key);\\\\r\\\\n\\\\t\\\\t\\\\t\\\\t              ^^^^^^^^^^^\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandleNone\' as preHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult\r\nimport \'@/public/toHump\' as toHump\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"appLabels\":appLabels\r\n}\r\n\r\npreHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT${step}S\',\'zero\') AS stat_time, app AS app_label, SUM(sent_bytes + received_bytes) AS bytes_total, SUM(sent_pkts + received_pkts) AS packets_total, SUM(sessions) AS sessions_total FROM metric_application WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND app IN (<#if appLabels?default(\'\')?trim? length gt 0> ${appLabels} </#if>) GROUP BY stat_time,app_label ORDER BY stat_time ASC\\\",\\\"option\\\":\\\"real_time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"overviewApplicationTrafficAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new ArrayList();\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		var name = new HashMap();\r\n		for(i,j in list){\r\n			var temp = list[i];\r\n			var tempObj= {};\r\n			for (key,value in temp){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = temp[key];\r\n				if(tempKey == \'appLabel\'){\r\n					name.put(tempObj[tempKey],tempObj[tempKey]);\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		var type = {};\r\n		type.bytes = \'bytesTotal\';\r\n		type.packets = \'packetsTotal\';\r\n		type.sessions = \'sessionsTotal\';\r\n		for(key,value in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			for(m,n in name){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new ArrayList();\r\n				list.sort((a,b)=>a.statTime.asDouble()-b.statTime.asDouble());\r\n				var sumValue = 0;\r\n				for(i,j in list){\r\n					var pojo = list[i];\r\n					if(pojo[\"appLabel\"]==m){\r\n					var tempArray = new ArrayList();\r\n					tempArray.add(pojo[\"statTime\"]);\r\n					tempArray.add(pojo[type[key]] + \"\");\r\n					values.add(tempArray);\r\n					sumValue += pojo[type[key]].asDouble();\r\n					}\r\n				}\r\n				var plist = [];\r\n				for(i,j in values){\r\n					plist.push(values[i][1]);\r\n				}\r\n				analysis.rate = (sumValue/parameter.timeDiff).toFixed(2).asDouble() * 8;\r\n				analysis.total = sumValue;\r\n				\r\n				zong.values = values;\r\n				zong.analysis = analysis;\r\n				\r\n				obj[m] = zong;\r\n			}\r\n			old.add(obj);\r\n		}\r\n	}\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}\r\n\r\nreturn result;');
