: \"data\",\n      \"value\" : \"\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Object\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ {\n        \"name\" : \"resultType\",\n        \"value\" : \"object\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"String\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      }, {\n        \"name\" : \"result\",\n        \"value\" : \"\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"Array\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ {\n          \"name\" : \"\",\n          \"value\" : \"\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"Object\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ {\n            \"name\" : \"type\",\n            \"value\" : \"bytes\",\n            \"description\" : \"\",\n            \"required\" : false,\n            \"dataType\" : \"String\",\n            \"type\" : null,\n            \"defaultValue\" : null,\n            \"validateType\" : \"\",\n            \"error\" : \"\",\n            \"expression\" : \"\",\n            \"children\" : [ ]\n          }, {\n            \"name\" : \"Jingdong\",\n            \"value\" : \"\",\n            \"description\" : \"\",\n            \"required\" : false,\n            \"dataType\" : \"Object\",\n            \"type\" : null,\n            \"defaultValue\" : null,\n            \"validateType\" : \"\",\n            \"error\" : \"\",\n            \"expression\" : \"\",\n            \"children\" : [ {\n              \"name\" : \"rate\",\n              \"value\" : \"380824.0\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"Double\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ ]\n            }, {\n              \"name\" : \"total\",\n              \"value\" : \"171373801\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"Integer\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ ]\n            } ]\n          } ]\n        } ]\n      } ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/object\' as objHandle\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult\r\nimport \'@/public/toHump\' as toHump\r\nimport \'@/pre/typeHandle2nd\' as typeHandle2nd\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"appCompanies\":appCompanies\r\n}\r\n\r\npreHandle(parameter);\r\ntypeHandle2nd(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT app_company AS app_company, SUM(sent_bytes + received_bytes) AS bytes_total, SUM(sent_pkts + received_pkts) AS packets_total, SUM(sessions) AS sessions_total FROM metric_application WHERE stat_time >= ${startTime}-${timeDiff} AND stat_time < ${endTime}-${timeDiff} AND app_company IN (<#if appCompanies?default(\'\')?trim? length gt 0> ${appCompanies} </#if>) GROUP BY app_company\\\",\\\"option\\\":\\\"real_time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"overviewAppCompanyCycleTrafficTotal\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new ArrayList();\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		var name = new HashMap();\r\n		for(i,j in list){\r\n			var temp = list[i];\r\n			var tempObj= {};\r\n			for (key,value in temp){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = temp[key];\r\n				if(tempKey == \'appCompany\'){\r\n					name.put(tempObj[tempKey],tempObj[tempKey]);\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		var type = {};\r\n		type.bytes = \'bytesTotal\';\r\n		type.packets = \'packetsTotal\';\r\n		type.sessions = \'sessionsTotal\';\r\n		for(key,value in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			for(i in list){\r\n				for(m,n in i){\r\n					var pojo = {}\r\n					if(m==value){\r\n						pojo.rate=(n.asDouble()/parameter.timeDiff).toFixed(2).asDouble() * 8\r\n						pojo.total=n.asDouble();\r\n                        obj[i[\"appCompany\"]] = pojo;\r\n					}\r\n				}\r\n			}\r\n			old.add(obj);\r\n		}\r\n	}\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}\r\n\r\n\r\nreturn result;');
INSERT INTO `magic_api_file` VALUES ('/api/interface/overview/服务提供商流量统计曲线图.ms', '{\n  \"properties\" : { },\n  \"id\" : \"copy1673404403275d98505\",\n  \"script\" : null,\n  \"groupId\" : \"bc06ac0a0d374572bc3a94475f63b200\",\n  \"name\" : \"服务提供商流量统计曲线图\",\n  \"createTime\" : null,\n  \"updateTime\" : 1701672637207,\n  \"lock\" : null,\n  \"createBy\" : \"th\",\n  \"updateBy\" : \"admin\",\n  \"path\" : \"/appCompanyTrafficAnalysis\",\n  \"method\" : \"GET\",\n  \"parameters\" : [ {\n    \"name\" : \"startTime\",\n    \"value\" : \"1699056000\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"endTime\",\n    \"value\" : \"1699059000\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"appCompanies\",\n    \"value\" : \"\'Tencent\'\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : \"{\\n    \\\"status\\\": 200,\\n    \\\"code\\\": 200,\\n    \\\"queryKey\\\": \\\"f44e48a81788ac6af197839e758434c4\\\",\\n    \\\"success\\\": true,\\n    \\\"message\\\": null,\\n    \\\"statistics\\\": {\\n        \\\"elapsed\\\": 10,\\n        \\\"rows_read\\\": 1973107,\\n        \\\"bytes_read\\\": 40055179,\\n        \\\"result_size\\\": 0,\\n        \\\"result_rows\\\": 0\\n    },\\n    \\\"job\\\": null,\\n    \\\"formatType\\\": \\\"json\\\",\\n    \\\"meta\\\": [\\n        {\\n            \\\"name\\\": \\\"stat_time\\\",\\n            \\\"type\\\": \\\"long\\\",\\n            \\\"category\\\": \\\"Dimension\\\"\\n        },\\n        {\\n            \\\"name\\\": \\\"app_company\\\",\\n            \\\"type\\\": \\\"string\\\",\\n            \\\"category\\\": \\\"Dimension\\\"\\n        },\\n        {\\n            \\\"name\\\": \\\"bytes_total\\\",\\n            \\\"type\\\": \\\"long\\\",\\n            \\\"category\\\": \\\"Metric\\\"\\n        },\\n        {\\n            \\\"name\\\": \\\"packets_total\\\",\\n            \\\"type\\\": \\\"long\\\",\\n            \\\"category\\\": \\\"Metric\\\"\\n        },\\n        {\\n            \\\"name\\\": \\\"sessions_total\\\",\\n            \\\"type\\\": \\\"long\\\",\\n            \\\"category\\\": \\\"Metric\\\"\\n        }\\n    ],\\n    \\\"data\\\": {\\n        \\\"resultType\\\": \\\"object\\\",\\n        \\\"result\\\": []\\n    },\\n    \\\"originalUrl\\\": \\\"http://192.168.44.55:9999/sql/?query=SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT60S\',\'zero\') AS stat_time, app_company AS app_company, SUM(sent_bytes + received_bytes) AS bytes_total, SUM(sent_pkts + received_pkts) AS packets_total, SUM(sessions) AS sessions_total FROM metric_application WHERE stat_time >= toDateTime(1699056000) AND stat_time < toDateTime(1699059000) AND app_company IN ( \'bgp\' ) GROUP BY stat_time,app_company ORDER BY stat_time ASC&format=json&option=real_time\\\",\\n    \\\"msg\\\": \\\"OK\\\"\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/object\' as objHandle\r\nimport \'@/public/toHump\' as toHump\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult\r\nimport \'@/pre/typeHandle2nd\' as typeHandle2nd\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"appCompanies\":appCompanies\r\n}\r\n\r\npreHandle(parameter);\r\ntypeHandle2nd(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT${step}S\',\'zero\') AS stat_time, app_company AS app_company, SUM(sent_bytes + received_bytes) AS bytes_total, SUM(sent_pkts + received_pkts) AS packets_total, SUM(sessions) AS sessions_total FROM metric_application WHERE stat_time >= ${startTime} AND stat_time < ${endTime} <#if appCompanies?default(\'\')?trim? length gt 0>AND app_company IN (<#if appCompanies?default(\'\')?trim? length gt 0> ${appCompanies} </#if>)</#if> GROUP BY stat_time,app_company ORDER BY stat_time ASC\\\",\\\"option\\\":\\\"real_time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"overviewAppCompanyTrafficAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new ArrayList();\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		var name = new HashMap();\r\n		for(i,j in list){\r\n			var temp = list[i];\r\n			var tempObj= {};\r\n			for (key,value in temp){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = temp[key];\r\n				if(tempKey == \'appCompany\'){\r\n					name.put(tempObj[tempKey],tempObj[tempKey]);\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		var type = {};\r\n		type.bytes = \'bytesTotal\';\r\n		type.packets = \'packetsTotal\';\r\n		type.sessions = \'sessionsTotal\';\r\n		for(key,value in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			for(m,n in name){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new ArrayList();\r\n				list.sort((a,b)=>a.statTime.asDouble()-b.statTime.asDouble());\r\n				var sumValue = 0;\r\n				for(i,j in list){\r\n					var pojo = list[i];\r\n					if(pojo[\"appCompany\"]==m){\r\n					var tempArray = new ArrayList();\r\n					tempArray.add(pojo[\"statTime\"]);\r\n					tempArray.add(pojo[type[key]] + \"\");\r\n					values.add(tempArray);\r\n					sumValue += pojo[type[key]].asDouble();\r\n					}\r\n				}\r\n				var plist = [];\r\n				for(i,j in values){\r\n					plist.push(values[i][1]);\r\n				}\r\n				analysis.rate = (sumValue/parameter.timeDiff).toFixed(2).asDouble() * 8;\r\n				analysis.total = sumValue;\r\n				\r\n				zong.values = values;\r\n				zong.analysis = analysis;\r\n				\r\n				obj[m] = zong;\r\n			}\r\n			old.add(obj);\r\n		}\r\n	}\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}\r\n\r\nreturn result;');
