 >= toDateTime(1692320432) AND stat_time < toDateTime(1692324032) AND notEmpty(server_admin_area)  AND server_admin_area IN (\'China\')  AND side = \'server\'  GROUP BY server_admin_area  ORDER BY total_bytes desc   LIMIT 10 &format=json&option=real_time\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult\r\nimport \'@/pre/typeHandle6th\' as typeHandle6th\r\nimport \'@/public/orderHandle\' as orderHandle\r\nimport \'@/public/toHump\' as toHump\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"type\":type,\r\n    \"orderBy\":orderBy,\r\n    \"limit\":limit,\r\n	\"params\":params\r\n}\r\nparameter.orderBy = orderHandle(parameter.orderBy);\r\npreHandle(parameter);\r\ntypeHandle6th(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT ${fieldName} AS ${lad},SUM(sent_bytes + received_bytes) AS total_bytes,SUM(traffic_inbound_byte) AS inbound_bytes,SUM(traffic_outbound_byte) AS outbound_bytes,SUM(traffic_internal_byte) AS internal_bytes,SUM(traffic_through_byte) AS through_bytes,SUM(sent_pkts + received_pkts) AS total_packets,SUM(traffic_inbound_pkt) AS inbound_packets,SUM(traffic_outbound_pkt) AS outbound_packets,SUM(traffic_internal_pkt) AS internal_packets,SUM(traffic_through_pkt) AS through_packets,SUM(sessions) AS sessions FROM ${tableName} WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND notEmpty(${lad}) <#if params?default(\'\')?trim? length gt 0> AND ${lad} IN (${params})</#if> <#if filter?default(\'\')?trim? length gt 0> ${filter} </#if> GROUP BY ${lad} <#if orderBy?default(\'\')?trim? length gt 0> ORDER BY ${orderBy} desc <#else> ORDER BY total_bytes desc </#if> <#if limit?default(\'\')?trim? length gt 0> LIMIT ${limit} </#if>\\\",\\\"option\\\":\\\"real_time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"overviewDimensionTrafficAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(i,j in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (key,value in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key.indexOf(\"total_bytes\") != -1){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"total_packets\") != -1){\r\n					tempObj[\'totalPacketsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"total_sessions\") != -1){\r\n					tempObj[\'totalSessionsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"inbound_packets\") != -1){\r\n					tempObj[\'inboundPacketsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"outbound_packets\") != -1){\r\n					tempObj[\'outboundPacketsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"internal_bytes\") != -1){\r\n					tempObj[\'internalBitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"internal_packets\") != -1){\r\n					tempObj[\'internalPacketsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"through_bytes\") != -1){\r\n					tempObj[\'throughBitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"through_packets\") != -1){\r\n					tempObj[\'throughPacketsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"sessions\") != -1){\r\n					tempObj[\'sessionsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
