'@/public/postGalaxyResult\' as postGalaxyResult\r\nimport \'@/pre/typeHandle6th\' as typeHandle6th\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"type\":type,\r\n    \"params\":params\r\n}\r\n\r\npreHandle(parameter);\r\ntypeHandle6th(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT ${fieldName} AS ${lad},ROUND(AVG(tcp_lost_bytes_ratio), 4) AS tcp_lostlen_percent FROM ${tableName} WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND isNotNull(tcp_lost_bytes_ratio) AND ${lad} IN (<#if params?default(\'\')?trim? length gt 0> ${params} </#if>)<#if filter?default(\'\')?trim? length gt 0> ${filter} </#if> GROUP BY ${lad}\\\",\\\"option\\\":\\\"real_time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"overviewDimensionTcpLostlenPercent\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = postGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = objHandle(galaxyRes);\r\n\r\nreturn result;');
