   } ]\n  }\n}\r\n================================\r\nimport cn.hutool.core.util.ObjectUtil\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/pageFieldsHandle\' as pageHandle;\r\nimport \'@/post/table\' as postHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"entityType\":entityType,\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"pageNo\":pageNo,\r\n    \"pageSize\":pageSize\r\n}\r\nif (ObjectUtil.isEmpty(parameter.endTime)) {\r\n    parameter.endTime = new Date().getTime()/1000;\r\n}\r\nif (ObjectUtil.isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 30 * 86400;\r\n}\r\npageHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT entity_type AS entity_type, server_ip AS server_ip, domain AS domain, app_name AS app_name, event_severity AS event_severity, event_type AS event_type, start_time AS start_time, duration_ms AS duration_ms, end_time AS end_time FROM performance_event WHERE start_time >= ${startTime} AND start_time < ${endTime} <#if entityType?default(\\\'\\\')?trim? length gt 0 && resource?default(\\\'\\\')?trim? length gt 0> <#if entityType==\\\"app\\\"> AND app_name=\\\'${resource}\\\' <#elseif entityType==\\\"domain\\\"> AND domain=\\\'${resource}\\\' <#elseif entityType==\\\"ip\\\"> AND server_ip=\\\'${resource}\\\' </#if> </#if> ORDER BY start_time DESC <#if pageSize?default(\\\'\\\')?trim? length gt 0&&pageNo?default(\\\'\\\')?trim? length gt 0> LIMIT ${pageNo},${pageSize}</#if>\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityDetailEventPerformanceEntityType\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = postGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nresult.data.pageNo = ObjectUtil.isNotEmpty(pageNo) ? pageNo : 1;\r\nresult.data.pageSize = ObjectUtil.isNotEmpty(pageSize) ? pageSize : parameter.pageSize;\r\nresult.data.total = result.data.result.length;\r\nresult.msg = \"success\";\r\nprintln(jsonUtil.toJsonStr(result));\r\nreturn result;');
