\n          \"dataType\" : \"String\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        }, {\n          \"name\" : \"type\",\n          \"value\" : \"long\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"String\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        }, {\n          \"name\" : \"category\",\n          \"value\" : \"Metric\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"String\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        } ]\n      } ]\n    }, {\n      \"name\" : \"data\",\n      \"value\" : \"\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Object\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ {\n        \"name\" : \"resultType\",\n        \"value\" : \"table\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"String\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      }, {\n        \"name\" : \"result\",\n        \"value\" : \"\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"Array\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      }, {\n        \"name\" : \"pageNo\",\n        \"value\" : \"1\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"Integer\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      }, {\n        \"name\" : \"pageSize\",\n        \"value\" : \"10\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"Integer\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      }, {\n        \"name\" : \"total\",\n        \"value\" : \"0\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"Integer\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      } ]\n    }, {\n      \"name\" : \"originalUrl\",\n      \"value\" : \"http://192.168.44.55:9999/?query=SELECT event_id AS event_id, security_type AS security_type, domain AS domain, offender_ip AS offender_ip, victim_ip AS victim_ip,client_ip AS client_ip,server_ip AS server_ip, event_severity AS event_severity, malware_name AS malware_name, cryptomining_pool AS cryptomining_pool, start_time AS start_time, duration_ms AS duration_ms, end_time AS end_time FROM security_event WHERE start_time >= 1690945947 AND start_time < 1693537947   AND app_name=\'bittorrent\'   ORDER BY start_time DESC  LIMIT 0,10&format=json&option=real_time\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"success\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport cn.hutool.core.util.ObjectUtil\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/pageFieldsHandle\' as pageHandle;\r\nimport \'@/post/table\' as postHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"entityType\":entityType,\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"pageNo\":pageNo,\r\n    \"pageSize\":pageSize\r\n}\r\nif (ObjectUtil.isEmpty(parameter.endTime)) {\r\n    parameter.endTime = new Date().getTime()/1000;\r\n}\r\nif (ObjectUtil.isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 30 * 86400;\r\n}\r\npageHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT event_id AS event_id, event_type AS event_type, event_name AS event_name, event_key AS event_key, rule_id AS rule_id, rule_type AS rule_type, is_builtin AS is_builtin, severity AS event_severity, offender_ip AS offender_ip, victim_ip AS victim_ip, domain AS domain, app AS app, start_time AS start_time, end_time AS end_time, duration_s AS duration_s, match_times AS match_times, status AS status, event_info AS event_info FROM cn_security_event WHERE start_time >= ${startTime} AND start_time < ${endTime} <#if entityType?default(\\\'\\\')?trim? length gt 0 && resource?default(\\\'\\\')?trim? length gt 0> <#if entityType==\\\"app\\\"> AND app=\\\'${resource}\\\' <#elseif entityType==\\\"domain\\\"> AND domain=\\\'${resource}\\\' <#elseif entityType==\\\"ip\\\"> AND (offender_ip=\\\'${resource}\\\' or victim_ip=\\\'${resource}\\\') </#if> </#if> ORDER BY start_time DESC <#if pageSize?default(\\\'\\\')?trim? length gt 0&&pageNo?default(\\\'\\\')?trim? length gt 0> LIMIT ${pageNo},${pageSize}</#if>\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityDetailEventSecurityEntityType\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = postGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nresult.data.pageNo = ObjectUtil.isNotEmpty(pageNo) ? pageNo : 1;\r\nresult.data.pageSize = ObjectUtil.isNotEmpty(pageSize) ? pageSize : parameter.pageSize;\r\nresult.data.total = result.data.result.length;\r\nresult.msg = \"success\";\r\nprintln(jsonUtil.toJsonStr(result));\r\nreturn result;');
