,\\n                \\\"inbound_pkts\\\": \\\"753\\\",\\n                \\\"outbound_bytes\\\": \\\"93640\\\",\\n                \\\"outbound_pkts\\\": \\\"490\\\"\\n            },\\n            {\\n                \\\"app\\\": \\\"bing\\\",\\n                \\\"inbound_bytes\\\": \\\"739195\\\",\\n                \\\"inbound_pkts\\\": \\\"633\\\",\\n                \\\"outbound_bytes\\\": \\\"49082\\\",\\n                \\\"outbound_pkts\\\": \\\"265\\\"\\n            },\\n            {\\n                \\\"app\\\": \\\"ms_edge\\\",\\n                \\\"inbound_bytes\\\": \\\"78314\\\",\\n                \\\"inbound_pkts\\\": \\\"167\\\",\\n                \\\"outbound_bytes\\\": \\\"194869\\\",\\n                \\\"outbound_pkts\\\": \\\"217\\\"\\n            },\\n            {\\n                \\\"app\\\": \\\"windows_update\\\",\\n                \\\"inbound_bytes\\\": \\\"123001\\\",\\n                \\\"inbound_pkts\\\": \\\"194\\\",\\n                \\\"outbound_bytes\\\": \\\"5034\\\",\\n                \\\"outbound_pkts\\\": \\\"54\\\"\\n            },\\n            {\\n                \\\"app\\\": \\\"http2\\\",\\n                \\\"inbound_bytes\\\": \\\"59220\\\",\\n                \\\"inbound_pkts\\\": \\\"69\\\",\\n                \\\"outbound_bytes\\\": \\\"8389\\\",\\n                \\\"outbound_pkts\\\": \\\"46\\\"\\n            },\\n            {\\n                \\\"app\\\": \\\"wecom\\\",\\n                \\\"inbound_bytes\\\": \\\"41430\\\",\\n                \\\"inbound_pkts\\\": \\\"92\\\",\\n                \\\"outbound_bytes\\\": \\\"20687\\\",\\n                \\\"outbound_pkts\\\": \\\"88\\\"\\n            },\\n            {\\n                \\\"app\\\": \\\"google_api\\\",\\n                \\\"inbound_bytes\\\": \\\"27477\\\",\\n                \\\"inbound_pkts\\\": \\\"31\\\",\\n                \\\"outbound_bytes\\\": \\\"5487\\\",\\n                \\\"outbound_pkts\\\": \\\"23\\\"\\n            },\\n            {\\n                \\\"app\\\": \\\"gravatar\\\",\\n                \\\"inbound_bytes\\\": \\\"11939\\\",\\n                \\\"inbound_pkts\\\": \\\"21\\\",\\n                \\\"outbound_bytes\\\": \\\"12537\\\",\\n                \\\"outbound_pkts\\\": \\\"24\\\"\\n            }\\n        ]\\n    },\\n    \\\"originalUrl\\\": \\\"http://192.168.44.55:9999/v1/query/sql\\\",\\n    \\\"msg\\\": \\\"OK\\\"\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport cn.hutool.core.util.ObjectUtil;\r\nimport \'@/pre/timeHandleNone\' as timeHandle;\r\nimport \'@/post/tableNotToHump\' as postHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"limit\":ObjectUtil.isNotEmpty(limit)?limit:10\r\n}\r\ntimeHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT app AS app, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_inbound_pkt) AS inbound_pkts, SUM(traffic_outbound_byte) AS outbound_bytes, SUM(traffic_outbound_pkt) AS outbound_pkts FROM metric_subscriber_app WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND notEmpty(app) AND subscriber_id = \'${resource}\' GROUP BY app ORDER BY SUM(sent_bytes + received_bytes) DESC limit ${limit}\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityDetailSubscriberRelateApps\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = postGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\n\r\nreturn result');
