   },\\n    \\\"meta\\\": [\\n        {\\n            \\\"name\\\": \\\"stat_time\\\",\\n            \\\"type\\\": \\\"long\\\",\\n            \\\"category\\\": \\\"Dimension\\\"\\n        },\\n        {\\n            \\\"name\\\": \\\"subscriber_id\\\",\\n            \\\"type\\\": \\\"string\\\",\\n            \\\"category\\\": \\\"Metric\\\"\\n        },\\n        {\\n            \\\"name\\\": \\\"subscriber_longitude\\\",\\n            \\\"type\\\": \\\"double\\\",\\n            \\\"category\\\": \\\"Dimension\\\"\\n        },\\n        {\\n            \\\"name\\\": \\\"subscriber_latitude\\\",\\n            \\\"type\\\": \\\"double\\\",\\n            \\\"category\\\": \\\"Dimension\\\"\\n        }\\n    ],\\n    \\\"data\\\": {\\n        \\\"resultType\\\": \\\"table\\\",\\n        \\\"result\\\": []\\n    },\\n    \\\"originalUrl\\\": \\\"http://192.168.44.55:9999/v1/query/sql\\\",\\n    \\\"msg\\\": \\\"OK\\\"\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandleNone\' as timeHandle;\r\nimport \'@/post/tableNotToHump\' as postHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\ntimeHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT${step}S\',\'zero\') AS stat_time, \'${resource}\' AS subscriber_id, subscriber_longitude AS subscriber_longitude, subscriber_latitude AS subscriber_latitude FROM metric_subscriber_app WHERE subscriber_longitude is not null AND subscriber_latitude is not null AND stat_time >= ${startTime} AND stat_time < ${endTime} AND subscriber_id = \'${resource}\' GROUP BY stat_time,subscriber_longitude,subscriber_latitude ORDER BY stat_time ASC\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityDetailSubscriberTrack\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\n\r\nif(result.success){\r\n    var o={};\r\n    o.resultType=\"table\";\r\n 	var list = result.data;\r\n	var newList = new ArrayList();\r\n	if(list.length > 0){\r\n		newList.add(list[0]);\r\n		var index = 0;\r\n		for(i,j in list) {\r\n			if(i > 0 && j.subscriber_id.equals(newList[index].subscriber_id) && j.subscriber_longitude.equals(newList[index].subscriber_longitude) && j.subscriber_latitude.equals(newList[index].subscriber_latitude)){\r\n				continue;\r\n			} else if(i > 0){\r\n				newList.add(j);\r\n				index++;\r\n			}\r\n		}\r\n	}\r\n	o.result = newList;\r\n    result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result');
