INSERT INTO `magic_api_file` VALUES ('/api/v1/entity/detail/traffic/overview/Subscriber流量统计.ms', '{\n  \"properties\" : { },\n  \"id\" : \"3e95cb518e51423ca43694be4d9886a1\",\n  \"script\" : null,\n  \"groupId\" : \"b657837f0b3d4a2db51b67e3fafadfd1\",\n  \"name\" : \"Subscriber流量统计\",\n  \"createTime\" : null,\n  \"updateTime\" : 1711006484595,\n  \"lock\" : null,\n  \"createBy\" : \"admin\",\n  \"updateBy\" : \"admin\",\n  \"path\" : \"/subscriber\",\n  \"method\" : \"GET\",\n  \"parameters\" : [ {\n    \"name\" : \"resource\",\n    \"value\" : \"gary6411\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"startTime\",\n    \"value\" : \"1704935668\",\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"endTime\",\n    \"value\" : \"1704939268\",\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"cycle\",\n    \"value\" : \"\",\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"Integer\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : \"{\\n    \\\"code\\\": 999,\\n    \\\"time\\\": \\\"2024-01-11 09:59:25\\\",\\n    \\\"message\\\": \\\"400 null at Row:13~13,Col:32~37\\\\n\\\\nvar galaxyResult = httpRequest.post().getBody();\\\\r\\\\n                               ^^^^^^            \\\"\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport net.geedge.common.utils.R as R;\r\nimport cn.hutool.core.util.ObjectUtil;\r\nimport \'@/pre/timeHandleNone\' as timeHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"cycle\":ObjectUtil.isNotEmpty(cycle)?cycle:0\r\n}\r\ntimeHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT SUM(sent_bytes + received_bytes) AS total_bytes, SUM(sent_pkts + received_pkts) AS total_packets, ROUND(total_bytes * 8 / ${timeDiff}) AS avg_bits_per_sec, ROUND(total_packets /${timeDiff}) AS avg_pkts_per_sec, ROUND(AVG(avg_http_response_latency_ms), 4) AS avg_http_response_latency_ms, ROUND(AVG(avg_ssl_handshake_latency_ms), 4) AS avg_ssl_handshake_latency_ms, ROUND(AVG(tcp_lost_bytes_ratio), 4) AS tcp_lost_bytes_ratio FROM metric_subscriber_app WHERE <#if cycle==0>stat_time >= ${startTime} AND stat_time < ${endTime} <#else>stat_time >= ${startTime}-${timeDiff} AND stat_time < ${endTime}-${timeDiff}</#if> AND subscriber_id = \'${resource}\'\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityDetailTrafficOverviewSubscriber\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = postGalaxyResult(res);\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar data = {};\r\nif(galaxyRes.success){\r\n	if(galaxyRes.data.length > 0){\r\n        data = galaxyRes.data[0];\r\n    }\r\n}\r\n\r\nreturn R.ok(data).put(\"originalUrl\",galaxyRes.originalUrl).put(\"status\",200);');
