) AS receivedBytes,SUM(sent_pkts + received_pkts) AS packets ,    SUM(sessions) as sessions FROM     session_record_cn WHERE     recv_time >= ${startTime}     AND recv_time < ${endTime} 	AND  app   = \\\'${resource}\\\'  	<#if country?default(\\\'\\\')?trim? length gt 0> <#if province?default(\\\'\\\')?trim? length gt 0>AND server_country_region = \\\'${country}\\\'  AND server_super_admin_area = \\\'${province}\\\' AND server_admin_area != \\\'\\\' <#else> AND server_country_region = \\\'${country}\\\' AND server_super_admin_area != \\\'\\\' </#if> <#else> AND server_country_region != \\\'\\\' </#if> GROUP BY server_country_region <#if country?default(\\\'\\\')?trim? length gt 0>,server_super_admin_area <#if province?default(\\\'\\\')?trim? length gt 0>,server_admin_area</#if></#if>\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar domain = \"{\\r\\n    \\\"query\\\": \\\"SELECT server_country_region AS server_country_region,  <#if country?default(\\\'\\\')?trim? length gt 0> server_super_admin_area AS server_super_admin_area, <#if province?default(\\\'\\\')?trim? length gt 0> server_admin_area AS server_admin_area, </#if> </#if>     SUM(sent_bytes + received_bytes) AS bytes,SUM(sent_bytes) AS sentBytes, SUM(received_bytes) AS receivedBytes,SUM(sent_pkts + received_pkts) AS packets,     SUM(sessions) as sessions FROM     session_record_cn WHERE     recv_time >= ${startTime}     AND recv_time < ${endTime} 	AND  domain = \\\'${resource}\\\'  	<#if country?default(\\\'\\\')?trim? length gt 0> <#if province?default(\\\'\\\')?trim? length gt 0>AND server_country_region = \\\'${country}\\\'  AND server_super_admin_area = \\\'${province}\\\' AND server_admin_area != \\\'\\\' <#else> AND server_country_region = \\\'${country}\\\' AND server_super_admin_area != \\\'\\\' </#if> <#else> AND server_country_region != \\\'\\\' </#if> GROUP BY server_country_region <#if country?default(\\\'\\\')?trim? length gt 0>,server_su