o, 0.95), 4) AS tcp_lostlen_percent_p95, ROUND(QUANTILE(tcp_lost_bytes_ratio, 0.99), 4) AS tcp_lostlen_percent_p99, ROUND(AVG(tcp_rtx_pkts_ratio), 4) AS pkt_retrans_percent_avg, ROUND(QUANTILE(tcp_rtx_pkts_ratio, 0.5), 4) AS pkt_retrans_percent_p50, ROUND(QUANTILE(tcp_rtx_pkts_ratio, 0.9), 4) AS pkt_retrans_percent_p90, ROUND(QUANTILE(tcp_rtx_pkts_ratio, 0.95), 4) AS pkt_retrans_percent_p95, ROUND(QUANTILE(tcp_rtx_pkts_ratio, 0.99), 4) AS pkt_retrans_percent_p99, ROUND(AVG(avg_ssl_handshake_latency_ms)) AS ssl_con_latency_avg, ROUND(QUANTILE(avg_ssl_handshake_latency_ms,0.5)) AS ssl_con_latency_p50, ROUND(QUANTILE(avg_ssl_handshake_latency_ms)) AS ssl_con_latency_p90, ROUND(QUANTILE(avg_ssl_handshake_latency_ms,0.95)) AS ssl_con_latency_p95, ROUND(QUANTILE(avg_ssl_handshake_latency_ms,0.99)) AS ssl_con_latency_p99, ROUND(AVG(avg_http_response_latency_ms)) AS http_response_latency_avg, ROUND(QUANTILE(avg_http_response_latency_ms,0.5)) AS http_response_latency_p50, ROUND(QUANTILE(avg_http_response_latency_ms,0.9)) AS http_response_latency_p90, ROUND(QUANTILE(avg_http_response_latency_ms,0.95)) AS http_response_latency_p95, ROUND(QUANTILE(avg_http_response_latency_ms,0.99)) AS http_response_latency_p99, ROUND(AVG(avg_tcp_rtt_ms)) AS establish_latency_ms_avg, ROUND(QUANTILE(avg_tcp_rtt_ms,0.5)) AS establish_latency_ms_p50, ROUND(QUANTILE(avg_tcp_rtt_ms,0.9)) AS establish_latency_ms_p90, ROUND(QUANTILE(avg_tcp_rtt_ms,0.95)) AS establish_latency_ms_p95, ROUND(QUANTILE(avg_tcp_rtt_ms,0.99)) AS establish_latency_ms_p99 FROM metric_ip WHERE stat_time >= 1693458794 AND stat_time < 1693462394  AND ip=\'180.101.242.227\' AND side = \'server\' &format=json&option=real_time\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport \'@/pre/timeHandleNone\' as timeHandle;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/entity/entityTrafficHandle\' as entityTrafficHandle;\r\nimport \'@/post/object\' as postHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"entityType\":entityType,\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\nentityTrafficHandle(parameter);\r\ntimeHandle(parameter);\r\nstartTime = parameter.startTime;\r\nendTime = parameter.endTime;\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT ROUND(AVG(tcp_lost_bytes_ratio), 4) AS tcp_lostlen_percent_avg, ROUND(QUANTILE(tcp_lost_bytes_ratio, 0.5), 4) AS tcp_lostlen_percent_p50, ROUND(QUANTILE(tcp_lost_bytes_ratio, 0.9), 4) AS tcp_lostlen_percent_p90, ROUND(QUANTILE(tcp_lost_bytes_ratio, 0.95), 4) AS tcp_lostlen_percent_p95, ROUND(QUANTILE(tcp_lost_bytes_ratio, 0.99), 4) AS tcp_lostlen_percent_p99, ROUND(AVG(tcp_rtx_pkts_ratio), 4) AS pkt_retrans_percent_avg, ROUND(QUANTILE(tcp_rtx_pkts_ratio, 0.5), 4) AS pkt_retrans_percent_p50, ROUND(QUANTILE(tcp_rtx_pkts_ratio, 0.9), 4) AS pkt_retrans_percent_p90, ROUND(QUANTILE(tcp_rtx_pkts_ratio, 0.95), 4) AS pkt_retrans_percent_p95, ROUND(QUANTILE(tcp_rtx_pkts_ratio, 0.99), 4) AS pkt_retrans_percent_p99, ROUND(AVG(avg_ssl_handshake_latency_ms)) AS ssl_con_latency_avg, ROUND(QUANTILE(avg_ssl_handshake_latency_ms,0.5)) AS ssl_con_latency_p50, ROUND(QUANTILE(avg_ssl_handshake_latency_ms)) AS ssl_con_latency_p90, ROUND(QUANTILE(avg_ssl_handshake_latency_ms,0.95)) AS ssl_con_latency_p95, ROUND(QUANTILE(avg_ssl_handshake_latency_ms,0.99)) AS ssl_con_latency_p99, ROUND(AVG(avg_http_response_latency_ms)) AS http_response_latency_avg, ROUND(QUANTILE(avg_http_response_latency_ms,0.5)) AS http_response_latency_p50, ROUND(QUANTILE(avg_http_response_latency_ms,0.9)) AS http_response_latency_p90, ROUND(QUANTILE(avg_http_response_latency_ms,0.95)) AS http_response_latency_p95, ROUND(QUANTILE(avg_http_response_latency_ms,0.99)) AS http_response_latency_p99, ROUND(AVG(avg_tcp_rtt_ms)) AS establish_latency_ms_avg, ROUND(QUANTILE(avg_tcp_rtt_ms,0.5)) AS establish_latency_ms_p50, ROUND(QUANTILE(avg_tcp_rtt_ms,0.9)) AS establish_latency_ms_p90, ROUND(QUANTILE(avg_tcp_rtt_ms,0.95)) AS establish_latency_ms_p95, ROUND(QUANTILE(avg_tcp_rtt_ms,0.99)) AS establish_latency_ms_p99 FROM ${tableName} WHERE stat_time >= ${startTime} AND stat_time < ${endTime} <#if entityType?default(\\\'\\\')?trim? length gt 0 && entityType==\\\"app\\\"> AND app=\\\'${resource}\\\' <#elseif entityType?default(\\\'\\\')?trim? length gt 0 && entityType==\\\"domain\\\"> AND domain=\\\'${resource}\\\' <#elseif entityType?default(\\\'\\\')?trim? length gt 0 && entityType==\\\"ip\\\"> AND ip=\\\'${resource}\\\' AND side = \'server\' <#else> AND subscriber_id =\\\'${resource}\\\' </#if>\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityExplorerTraffic\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = postGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\n\r\nreturn result;');
