,\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar domain = \"{\\r\\n    \\\"query\\\": \\\"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(stat_time),\'PT${step}S\',\'zero\') AS stat_time, ROUND(SUM(sent_bytes + received_bytes) * 8/ ${step}) AS rate, ROUND(SUM(sent_bytes) * 8/ ${step}) AS sent_rate, ROUND(SUM(received_bytes) * 8/ ${step}) AS received_rate FROM metric_domain WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND domain = \'${resource}\' GROUP BY stat_time\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar subscriber = \"{\\r\\n    \\\"query\\\": \\\"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(stat_time),\'PT${step}S\',\'zero\') AS stat_time, ROUND(SUM(sent_bytes + received_bytes) * 8/ ${step}) AS rate, ROUND(SUM(sent_bytes) * 8/ ${step}) AS sent_rate, ROUND(SUM(received_bytes) * 8/ ${step}) AS received_rate FROM metric_subscriber_app WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND subscriber_id = \'${resource}\' GROUP BY stat_time\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar result = {};\r\nif (\"ip\".equals(parameter.entityType)) {\r\n    result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityExplorerDetailTrafficThroughput\",ip,parameter);\r\n} else if (\"app\".equals(parameter.entityType)) {\r\n    result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityExplorerDetailTrafficThroughput\",app,parameter);\r\n} else if (\"domain\".equals(parameter.entityType)) {\r\n    result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityExplorerDetailTrafficThroughput\",domain,parameter);\r\n} else if (\"subscriber\".equals(parameter.entityType)) {\r\n    result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityExplorerDetailTrafficThroughput\",subscriber,parameter);\r\n}\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = postGalaxyResult(res);\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
