n        \\\"list\\\": [\\n            {\\n                \\\"value\\\": \\\"mtproxy\\\",\\n                \\\"uniqueEntities\\\": \\\"10\\\"\\n            },\\n            {\\n                \\\"value\\\": \\\"OPRDNS\\\",\\n                \\\"uniqueEntities\\\": \\\"3\\\"\\n            },\\n            {\\n                \\\"value\\\": \\\"4G\\\",\\n                \\\"uniqueEntities\\\": \\\"2\\\"\\n            },\\n            {\\n                \\\"value\\\": \\\"i2p\\\",\\n                \\\"uniqueEntities\\\": \\\"2\\\"\\n            }\\n        ]\\n    },\\n    \\\"time\\\": \\\"2023-12-29 06:36:45\\\",\\n    \\\"originalUrl\\\": \\\"http://192.168.44.55:9999/v1/query/sql\\\",\\n    \\\"message\\\": \\\"success\\\",\\n    \\\"status\\\": 200\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : \"\",\r\n    \"error\" : \"\",\r\n    \"expression\" : \"\",\r\n    \"children\" : [ {\r\n      \"name\" : \"code\",\r\n      \"value\" : \"200\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Integer\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"data\",\r\n      \"value\" : \"\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Object\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ {\r\n        \"name\" : \"list\",\r\n        \"value\" : \"\",\r\n        \"description\" : \"\",\r\n        \"required\" : false,\r\n        \"dataType\" : \"Array\",\r\n        \"type\" : null,\r\n        \"defaultValue\" : null,\r\n        \"validateType\" : \"\",\r\n        \"error\" : \"\",\r\n        \"expression\" : \"\",\r\n        \"children\" : [ ]\r\n      } ]\r\n    }, {\r\n      \"name\" : \"time\",\r\n      \"value\" : \"2023-08-31 02:53:50\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"originalUrl\",\r\n      \"value\" : \"http://192.168.44.55:9999/?query=SELECT entity_tag as entity_tag, COUNTIF(DISTINCT(app_name),notEmpty(app_name)) as appCount, COUNTIF(DISTINCT(domain),notEmpty(domain)) as domainCount, COUNTIF(DISTINCT(ip),notEmpty(ip)) as ipCount, plus(ipCount,plus(appCount,domainCount)) AS totalCount FROM( SELECT e.app_name AS app_name, e.domain AS domain, e.ip AS ip, e.update_time AS update_time, arrayJoin(e.entity_tags) AS entity_tag FROM session_relation_domain_ip_app e  JOIN cn_ip_dynamic_attribute dr ON (e.ip = dr.ip)  WHERE e.update_time >= 1677898430 AND e.update_time < 1693450430 AND notEmpty(e.entity_tags) AND dr.update_time >= 1677898430 AND dr.update_time < 1693450430  AND (dr.port = 80)  ) GROUP BY entity_tag ORDER BY totalCount DESC limit 5&format=json&option=real_time\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"message\",\r\n      \"value\" : \"success\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"status\",\r\n      \"value\" : \"200\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Integer\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nimport cn.hutool.log.Log;\r\nimport cn.hutool.core.util.ObjectUtil;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport net.geedge.common.utils.R as R;\r\nimport net.geedge.modules.entity.service.EntityExplorerService as EntityExplorerService;\r\nimport \'@/public/toHump\' as toHump;\r\nimport \'@/pre/timeHandleHalf\' as timeHandle;\r\nimport \'@/entity/entityAggHandle\' as entityAggHandle;\r\nimport \'@/entity/entityHideHandle\' as entityHideHandle;\r\nimport \'@/entity/crossEntityFilterHandle\' as crossEntityFilterHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"dr\":false,\r\n    \"fqdnCategory\":false,\r\n    \"whois\":false,\r\n    \"appCategory\":false,\r\n    \"hideRelated\":ObjectUtil.isEmpty(hideRelated)?false:hideRelated,\r\n    \"is_ip_attribut_primary\":0,\r\n    \"is_app_attribut_primary\":0,\r\n    \"is_domain_attribut_primary\":0\r\n}\r\ntimeHandle(parameter);\r\n//过滤标签时处理\r\nif(ObjectUtil.isNotEmpty(parameter.resource) && parameter.resource.contains(\"has(\")) {\r\n    parameter.tags = EntityExplorerService.getTagsForFilter(parameter.resource);\r\n}\r\nentityAggHandle(parameter);\r\nentityHideHandle(parameter);\r\n//如果跨实体不查询返回空;如果单一实体和tag同时过滤只过滤该实体的tag\r\nif(crossEntityFilterHandle(parameter) != 0) {\r\n    return crossEntityFilterHandle(parameter);\r\n}\r\n\r\nif(ObjectUtil.isNotEmpty(parameter.filter) && parameter.filter.contains(\"has(e.entity_tags\")) {\r\n    parameter.is_ip_attribut_primary = 1;\r\n    parameter.is_app_attribut_primary = 1;\r\n    parameter.is_domain_attribut_primary = 1;\r\n}\r\n\r\nvar isAssociationQuery = EntityExplorerService.isAssociationQuery(parameter.resource,\"entityMetadata\");\r\nif(isAssociationQuery){\r\n    var sql = \"{\\\"sql\\\":\\\"SELECT entity_tags AS entity_tags, COUNT(DISTINCT(app_name)) FILTER (WHERE app_name != \'\') AS appCount, COUNT(DISTINCT(domain)) FILTER (WHERE domain != \'\') AS domainCount, COUNT(DISTINCT(ip)) FILTER (WHERE ip != \'\') AS ipCount, COUNT(DISTINCT(app_name)) FILTER (WHERE app_name != \'\') + COUNT(DISTINCT(domain)) FILTER (WHERE domain != \'\') + COUNT(DISTINCT(ip)) FILTER (WHERE ip != \'\') AS totalCount FROM( SELECT e.app_name AS app_name, e.domain AS domain, e.ip AS ip, e.update_time AS update_time, e.entity_tags AS entity_tags FROM clickhouse.cyber_narrator_galaxy.session_relation_domain_ip_app e <#if fqdnCategory> JOIN mysql.cn_api.cn_fqdn_category_built_in fqdnCategory ON (e.domain = fqdnCategory.fqdn <#if fqdnCategory\\.category_name?default(\'\')?trim? length gt 0> AND ${fqdnCategory\\.category_name} </#if> <#if fqdnCategory\\.category_group?default(\'\')?trim? length gt 0> AND ${fqdnCategory\\.category_group} </#if> <#if fqdnCategory\\.reputation_level?default(\'\')?trim? length gt 0> AND ${fqdnCategory\\.reputation_level}</#if>) </#if>	 <#if whois>JOIN mysql.cn_api.cn_fqdn_who_is_built_in whois ON (e.domain = whois.fqdn <#if whois\\.whois_domain?default(\'\')?trim? length gt 0> AND ${whois\\.whois_domain} </#if> <#if whois\\.whois_registrant_name?default(\'\')?trim? length gt 0> AND ${whois\\.whois_registrant_name}</#if>) </#if> <#if appCategory>JOIN mysql.cn_api.cn_app_category_built_in appCategory ON (e.app_name = appCategory.app_name <#if appCategory\\.app_category?default(\'\')?trim? length gt 0> AND ${appCategory\\.app_category} </#if> <#if appCategory\\.app_subcategory?default(\'\')?trim? length gt 0> AND ${appCategory\\.app_subcategory} </#if> <#if appCategory\\.app_risk?default(\'\')?trim? length gt 0> AND ${appCategory\\.app_risk}</#if>) </#if> <#if dr\\.port?default(\'\')?trim? length gt 0>JOIN clickhouse.cyber_narrator_galaxy.cn_ip_dynamic_attribute dr ON (e.ip = dr.ip AND ${dr\\.port}) </#if> WHERE e.update_time >= ${startTime} AND e.update_time < ${endTime} AND entity_tags != \'\' <#if filter?default(\'\')?trim? length gt 0> ${filter} </#if> ) GROUP BY entity_tags ORDER BY totalCount DESC\\\"}\"\r\n    var aTemplate  = freeMarkerUtil.processTemplateIntoString(\"v1EntityExplorerTopAggTag\",sql,parameter);\r\n    var ares = jsonUtil.toBean(aTemplate,HashMap.class);\r\n    var log = Log.get();\r\n    log.info(ares.sql);\r\n    var aresult = db[\'trino\'].select(ares.sql);\r\n    var list=new ArrayList();\r\n    if(ObjectUtil.isNotEmpty(aresult)){\r\n        if(aresult.length > 0){\r\n            for(key,value in aresult){\r\n                var obj = {};\r\n                obj.value = value.entity_tags;\r\n                obj.uniqueEntities = value.totalCount;\r\n                list.add(obj);\r\n            }\r\n        }\r\n    }\r\n    var data = {};\r\n    data.list = list;\r\n    var url = db.select(\"select cvalue from sys_config where ckey = \'galaxy_url\'\");\r\n    return R.ok(data).put(\"originalUrl\",url.cvalue+ares.sql);\r\n}\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT entity_tag AS entity_tag, COUNTIF(DISTINCT(ip),notEmpty(ip)) AS ip_count, COUNTIF(DISTINCT(app_name),notEmpty(app_name)) AS app_count, COUNTIF(DISTINCT(domain),notEmpty(domain)) AS domain_count, plus(ip_count, plus(app_count, domain_count)) AS total_count FROM ( SELECT SUBSTRING(arrayJoin(entity_tags), position(arrayJoin(entity_tags), \'.\') + 1) AS entity_tag, IF(has(entity_tags, concat(\'ip.\', entity_tag)) AND notEmpty(ip) <#if hideRelated> AND ${is_ip_attribut_primary} </#if>, ip, \'\') AS ip, IF(has(entity_tags, concat(\'app.\', entity_tag)) AND notEmpty(app_name) <#if hideRelated> AND ${is_app_attribut_primary} </#if>, app_name, \'\') AS app_name, IF(has(entity_tags, concat(\'domain.\', entity_tag)) AND notEmpty(domain) <#if hideRelated> AND ${is_domain_attribut_primary} </#if>, domain, \'\') AS domain FROM cyber_narrator_galaxy.session_relation_domain_ip_app e <#if dr> JOIN cn_ip_dynamic_attribute dr ON (e.ip = dr.ip) </#if> WHERE e.update_time >= ${startTime} AND e.update_time < ${endTime} <#if dr> AND dr.update_time >= ${startTime} AND dr.update_time < ${endTime} </#if> AND notEmpty(entity_tags) <#if filter?default(\\\'\\\')?trim? length gt 0> AND (${filter}) </#if> GROUP BY entity_tags,app_name,ip,domain ) GROUP BY entity_tag HAVING total_count > 0 ORDER BY total_count DESC limit 100\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityExplorerTopAggTag\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(res);\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar data = {};\r\nvar list = new ArrayList();\r\nif(result.success){\r\n    for(key,value in result.data){\r\n        var obj = {};\r\n        obj.value = value.entity_tag;\r\n        obj.uniqueEntities = value.total_count;\r\n        list.add(obj);\r\n    }\r\n}\r\ndata.list = list;\r\nreturn R.ok(data).put(\"originalUrl\",result.originalUrl).put(\"status\",200);');
