t, COUNTIF(DISTINCT(ip),notEmpty(ip)) as ipCount, plus(ipCount,plus(appCount,domainCount)) AS totalCount FROM( SELECT e.app_name AS app_name, e.domain AS domain, e.ip AS ip, e.update_time AS update_time, e.ip_admin_area AS ip_admin_area, dr.port AS port, dr.l7_protocol AS l7_protocol FROM session_relation_domain_ip_app e JOIN cn_ip_dynamic_attribute dr ON (e.ip = dr.ip) WHERE e.update_time >= 1677898486 AND e.update_time < 1693450486) GROUP BY port,l7_protocol ORDER BY totalCount DESC limit 5&format=json&option=real_time\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"message\",\r\n      \"value\" : \"success\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"status\",\r\n      \"value\" : \"200\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Integer\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nimport cn.hutool.log.Log;\r\nimport cn.hutool.core.util.ObjectUtil;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport net.geedge.common.utils.R as R;\r\nimport \'@/public/toHump\' as toHump;\r\nimport net.geedge.modules.entity.service.EntityExplorerService as EntityExplorerService;\r\nimport \'@/pre/timeHandleHalf\' as timeHandle;\r\nimport \'@/entity/entityAggHandle\' as entityAggHandle;\r\nimport \'@/entity/entityHideHandle\' as entityHideHandle;\r\nimport \'@/entity/crossEntityFilterHandle\' as crossEntityFilterHandle;\r\nimport \'@/entity/notQueryHandle\' as notQueryHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"dr\":false,\r\n    \"fqdnCategory\":false,\r\n    \"whois\":false,\r\n    \"appCategory\":false,\r\n    \"hideRelated\":ObjectUtil.isEmpty(hideRelated)?false:hideRelated,\r\n    \"is_ip_attribut_primary\":0,\r\n    \"is_app_attribut_primary\":0,\r\n    \"is_domain_attribut_primary\":0\r\n}\r\ntimeHandle(parameter);\r\n//过滤标签时处理\r\nif(ObjectUtil.isNotEmpty(parameter.resource) && parameter.resource.contains(\"has(\")) {\r\n    parameter.tags = EntityExplorerService.getTagsForFilter(parameter.resource);\r\n}\r\nentityAggHandle(parameter);\r\nentityHideHandle(parameter);\r\n//如果跨实体不查询返回空;如果单一实体和tag同时过滤只过滤该实体的tag\r\nif(crossEntityFilterHandle(parameter) != 0) {\r\n    return crossEntityFilterHandle(parameter);\r\n}\r\n\r\nif(ObjectUtil.isNotEmpty(parameter.filter) && hideRelated && !parameter.filter.contains(\"has(e.entity_tags\") && parameter.is_ip_attribut_primary == 0) {\r\n    return notQueryHandle();\r\n}\r\n\r\nvar isAssociationQuery = EntityExplorerService.isAssociationQuery(parameter.resource,\"entityMetadata\");\r\nif(isAssociationQuery){\r\n    var sql = \"{\\\"sql\\\":\\\"SELECT port AS port, l7_protocol AS l7_protocol, COUNT(DISTINCT(ip)) FILTER (WHERE ip != \'\') AS count FROM( SELECT e.app_name AS app_name, e.domain AS domain, e.ip AS ip, e.update_time AS update_time, dr.port AS port, dr.l7_protocol AS l7_protocol FROM clickhouse.cyber_narrator_galaxy.session_relation_domain_ip_app e JOIN clickhouse.cyber_narrator_galaxy.cn_ip_dynamic_attribute dr ON (e.ip = dr.ip AND dr.update_time >= ${startTime} AND dr.update_time < ${endTime} <#if dr\\.port?default(\'\')?trim? length gt 0> AND ${dr\\.port}</#if>) <#if fqdnCategory> JOIN mysql.cn_api.cn_fqdn_category_built_in fqdnCategory ON (e.domain = fqdnCategory.fqdn <#if fqdnCategory\\.category_name?default(\'\')?trim? length gt 0> AND ${fqdnCategory\\.category_name} </#if> <#if fqdnCategory\\.category_group?default(\'\')?trim? length gt 0> AND ${fqdnCategory\\.category_group} </#if> <#if fqdnCategory\\.reputation_level?default(\'\')?trim? length gt 0> AND ${fqdnCategory\\.reputation_level}</#if>) </#if> <#if whois> JOIN mysql.cn_api.cn_fqdn_who_is_built_in whois ON (e.domain = whois.fqdn <#if whois\\.whois_domain?default(\'\')?trim? length gt 0> AND ${whois\\.whois_domain} </#if> <#if whois\\.whois_registrant_name?default(\'\')?trim? length gt 0> AND ${whois\\.whois_registrant_name}</#if>) </#if> <#if appCategory> JOIN mysql.cn_api.cn_app_category_built_in appCategory ON (e.app_name = appCategory.app_name <#if appCategory\\.app_category?default(\'\')?trim? length gt 0> AND ${appCategory\\.app_category} </#if> <#if appCategory\\.app_subcategory?default(\'\')?trim? length gt 0> AND ${appCategory\\.app_subcategory} </#if> <#if appCategory\\.app_risk?default(\'\')?trim? length gt 0> AND ${appCategory\\.app_risk}</#if>) </#if> WHERE e.update_time >= ${startTime} AND e.update_time < ${endTime} <#if filter?default(\'\')?trim? length gt 0> ${filter} </#if> ) GROUP BY port,l7_protocol ORDER BY count DESC\\\"}\"\r\n    var aTemplate  = freeMarkerUtil.processTemplateIntoString(\"v1EntityExplorerTopAggPort\",sql,parameter);\r\n    var ares = jsonUtil.toBean(aTemplate,HashMap.class);\r\n    var log = Log.get();\r\n    log.info(ares.sql);\r\n    var aresult = db[\'trino\'].select(ares.sql);\r\n    var list=new ArrayList();\r\n    if(ObjectUtil.isNotEmpty(aresult)){\r\n        if(aresult.length > 0){\r\n            for(key,value in aresult){\r\n                var obj = {};\r\n                obj.port = value.port;\r\n                obj.l7Protocol = value.l7_protocol;\r\n                obj.uniqueEntities = value.count;\r\n                list.add(obj);\r\n            }\r\n        }\r\n    }\r\n    var data = {};\r\n    data.list = list;\r\n    var url = db.select(\"select cvalue from sys_config where ckey = \'galaxy_url\'\");\r\n    return R.ok(data).put(\"originalUrl\",url.cvalue+ares.sql).put(\"status\",200);\r\n}\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT port AS port, l7_protocol AS l7_protocol, COUNTIF(DISTINCT(ip),notEmpty(ip)) as count FROM( SELECT e.app_name AS app_name, e.domain AS domain, e.ip AS ip, e.update_time AS update_time, e.ip_admin_area AS ip_admin_area, <#if tags?exists> if(<#list tags as tag><#if !tag_has_next> has(e.entity_tags, concat(\'ip.\', ${tag})) <#else> has(e.entity_tags, concat(\'ip.\', ${tag})) OR </#if></#list>, 1 , 0) AS is_ip_tag_primary ,if(<#list tags as tag><#if !tag_has_next> has(e.entity_tags, concat(\'app.\', ${tag})) <#else> has(e.entity_tags, concat(\'app.\', ${tag})) OR </#if></#list>, 1, 0) AS is_app_tag_primary ,if(<#list tags as tag><#if !tag_has_next> has(e.entity_tags, concat(\'domain.\', ${tag})) <#else> has(e.entity_tags, concat(\'domain.\', ${tag})) OR </#if></#list>, 1, 0) AS is_domain_tag_primary, </#if> IF(<#if hideRelated> ${is_ip_attribut_primary} <#else> 1 </#if> <#if tags?exists> OR is_ip_tag_primary </#if>,dr.port,-1) as port, IF(<#if hideRelated>${is_ip_attribut_primary} <#else> 1 </#if> <#if tags?exists> OR is_ip_tag_primary </#if>,dr.l7_protocol,\'\') as l7_protocol FROM session_relation_domain_ip_app e JOIN cn_ip_dynamic_attribute dr ON (e.ip = dr.ip) WHERE e.update_time >= ${startTime} AND e.update_time < ${endTime} AND dr.update_time >= ${startTime} AND dr.update_time < ${endTime} AND (port >= 0 AND notEmpty(l7_protocol)) <#if filter?default(\\\'\\\')?trim? length gt 0> AND (${filter}) </#if> ) GROUP BY port,l7_protocol ORDER BY count DESC limit 100\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityExplorerTopAggTag\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(res);\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar data = {};\r\nvar list = new ArrayList();\r\nif(result.success){\r\n    for(key,value in result.data){\r\n        var obj = {};\r\n        obj.port = value.port;\r\n        obj.l7Protocol = value.l7_protocol;\r\n        obj.uniqueEntities = value.count;\r\n        list.add(obj);\r\n    }\r\n}\r\ndata.list = list;\r\nreturn R.ok(data).put(\"originalUrl\",result.originalUrl).put(\"status\",200);');
