\"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"message\",\n      \"value\" : \"success\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"status\",\n      \"value\" : \"200\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Integer\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport net.geedge.common.utils.R as R;\r\nimport \'@/pre/timeHandleHalf\' as timeHandle;\r\nimport \'@/pre/pageFieldsHandle\' as pageHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\nimport net.geedge.modules.entity.service.EntityService as EntityService;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"entityType\":\"ip\",\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"pageNo\":pageNo,\r\n    \"pageSize\":pageSize\r\n}\r\ntimeHandle(parameter);\r\npageHandle(parameter);\r\n\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT DISTINCT(ip) AS ip FROM session_relation_domain_ip_app WHERE update_time >= ${startTime} AND update_time < ${endTime} AND app_name = \\\'${resource}\\\' AND notEmpty(ip) ORDER BY update_time DESC <#if pageSize?default(\\\'\\\')?trim? length gt 0&&pageNo?default(\\\'\\\')?trim? length gt 0> LIMIT ${pageNo},${pageSize}</#if>\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityGraphRelationAppRelateIps\",q,parameter);\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = postGalaxyResult(res);\r\n\r\nvar data = {};\r\ndata.pageNo = parameter.pageNo;\r\ndata.pageSize = parameter.pageSize;\r\ndata.total = galaxyRes.data.length;\r\ndata.list = new ArrayList();\r\n\r\nvar entityType = \"ip\";\r\nfor(key,value in galaxyRes.data){\r\n    resource = value.ip;\r\n    var entity = {};\r\n    entity.vertex = value.ip;\r\n    entity.detail = EntityService.queryEntityDetail(entityType,resource).data;\r\n    data.list.add(entity);\r\n}\r\n\r\nvar url = db.select(\"select cvalue from sys_config where ckey = \'galaxy_url\'\");\r\nreturn R.ok(data).put(\"originalUrl\",url.cvalue+res.query).put(\"status\",200);');
