\n            \\\"phoneNumber\\\": \\\"923212016648\\\",\\n            \\\"apn\\\": \\\"warid\\\",\\n            \\\"hitCount\\\": 8223,\\n            \\\"longitude\\\": 116.372452,\\n            \\\"latitude\\\": 39.913832,\\n            \\\"active\\\": 1,\\n            \\\"isFollowed\\\": 0,\\n            \\\"country\\\": \\\"China\\\",\\n            \\\"superAdministrativeArea\\\": \\\"Beijing\\\",\\n            \\\"administrativeArea\\\": \\\"Beijing\\\"\\n        },\\n        {\\n            \\\"subscriberId\\\": \\\"test6434\\\",\\n            \\\"imei\\\": \\\"357629170016434\\\",\\n            \\\"imsi\\\": \\\"41003514146434\\\",\\n            \\\"phoneNumber\\\": \\\"923335886434\\\",\\n            \\\"apn\\\": \\\"www.6434test.com\\\",\\n            \\\"hitCount\\\": 7448,\\n            \\\"longitude\\\": 116.370041,\\n            \\\"latitude\\\": 39.944283,\\n            \\\"active\\\": 1,\\n            \\\"isFollowed\\\": 0,\\n            \\\"country\\\": \\\"China\\\",\\n            \\\"superAdministrativeArea\\\": \\\"Beijing\\\",\\n            \\\"administrativeArea\\\": \\\"Beijing\\\"\\n        },\\n        {\\n            \\\"subscriberId\\\": \\\"test6438\\\",\\n            \\\"imei\\\": \\\"357629192166438\\\",\\n            \\\"imsi\\\": \\\"410031921686438\\\",\\n            \\\"phoneNumber\\\": \\\"921921686438\\\",\\n            \\\"apn\\\": \\\"statistics.sfa\\\",\\n            \\\"hitCount\\\": 5850,\\n            \\\"longitude\\\": 116.374113,\\n            \\\"latitude\\\": 39.943599,\\n            \\\"active\\\": 1,\\n            \\\"isFollowed\\\": 0,\\n            \\\"country\\\": \\\"China\\\",\\n            \\\"superAdministrativeArea\\\": \\\"Beijing\\\",\\n            \\\"administrativeArea\\\": \\\"Beijing\\\"\\n        }\\n    ],\\n    \\\"originalUrl\\\": \\\"SELECT subscriber_id AS subscriberId, anyLast(imei) AS imei, anyLast(imsi) AS imsi, anyLast(phone_number) AS phoneNumber, anyLast(apn) AS apn, COUNT(*) AS hitCount,anyLast(subscriber_longitude) as longitude,anyLast(subscriber_latitude) as latitude FROM location_subscriber where stat_time >= 0 and stat_time < 111809020488  GROUP BY subscriber_id ORDER BY hitCount DESC  LIMIT 0,10\\\"\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport cn.hutool.core.util.ObjectUtil;\r\nimport cn.hutool.core.util.StrUtil;\r\nimport net.geedge.common.utils.GeoUtil;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport net.geedge.common.utils.R as R;\r\nimport net.geedge.modules.sys.shiro.ShiroUtils;\r\nimport java.util.stream.Collectors;\r\nimport \'@/pre/timeHandleNone\' as timeHandle;\r\nimport \'@/post/object\' as postHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\nimport \'@/pre/pageFieldsHandle\' as pageHandle;\r\nimport \'@get:/v1/locationIntelligence/followed/status\' as getStatus;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n	\"pageSize\":pageSize,\r\n    \"pageNo\":pageNo,\r\n	\"params\":params,\r\n    \"isFollowed\":isFollowed\r\n}\r\ntimeHandle(parameter);\r\npageHandle(parameter);\r\n\r\n/**\r\n * 查询所有关注的用户信息\r\n */\r\nvar userId = ShiroUtils.getUserId();\r\nvar followSubs = new ArrayList();\r\nvar sql = \"\"\"\r\n    select subscriber_id from user_subscriber where user_id = #{userId}\r\n\"\"\"\r\nfollowSubs = db.select(sql);\r\nvar isFollow = new ArrayList();\r\nif(followSubs !=null && followSubs.size()>0){\r\n    for(i,j in followSubs){\r\n        isFollow.add(followSubs[i].subscriber_id);\r\n    }\r\n}\r\nvar queryIds = isFollow.stream().map(s -> \"\'\" + s + \"\'\").collect(Collectors.joining(\", \"));\r\nif(ObjectUtil.isNotEmpty(isFollowed) && isFollowed == 1){\r\n    if(ObjectUtil.isEmpty(queryIds)){\r\n        queryIds=\"\'\'\";\r\n    }\r\n    if(ObjectUtil.isNotEmpty(params)){\r\n        parameter.params=parameter.params+\" and subscriber_id in (\"+queryIds+\")\";\r\n    }else{\r\n        parameter.params=\"subscriber_id in (\"+queryIds+\")\";\r\n    }\r\n}\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT subscriber_id AS subscriberId, anyLast(imei) AS imei, anyLast(imsi) AS imsi, anyLast(phone_number) AS phoneNumber, anyLast(apn) AS apn, COUNT(*) AS hitCount,anyLast(subscriber_longitude) as longitude,anyLast(subscriber_latitude) as latitude FROM location_subscriber where stat_time >= ${startTime} and stat_time < ${endTime} <#if params?default(\\\'\\\')?trim? length gt 0> and ${params} </#if> GROUP BY subscriber_id ORDER BY hitCount DESC,subscriber_id <#if pageSize?default(\\\'\\\')?trim? length gt 0&&pageNo?default(\\\'\\\')?trim? length gt 0> LIMIT ${pageNo},${pageSize}</#if>\\\",\\\"option\\\":\\\"real_time\\\",\\\"format\\\":\\\"json\\\"}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1LocationIntelligenceList\",q,parameter);\r\n\r\n\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = postGalaxyResult(res);\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(galaxyRes.data.length > 0 ){\r\n    var sIds = [];\r\n    for(i,j in galaxyRes.data){\r\n        sIds.push(galaxyRes.data[i].subscriberId);\r\n    }\r\n    var subscriberIds = sIds.stream().map(s -> \"\'\" + s + \"\'\").collect(Collectors.joining(\", \"));\r\n    var status = getStatus();\r\n    var idSub = {};\r\n    if(status.data.length > 0 ){\r\n        for(i,j in status.data){\r\n            idSub.put(status.data[i].subscriber_id,1);\r\n        }\r\n    }\r\n    \r\n    for(i,j in galaxyRes.data){\r\n        if(idSub.get(galaxyRes.data[i].subscriberId)==1){\r\n            galaxyRes.data[i].active=1;\r\n        }else{\r\n            galaxyRes.data[i].active=0;\r\n        }\r\n        if(isFollow.contains(galaxyRes.data[i].subscriberId)){\r\n            galaxyRes.data[i].isFollowed=1;\r\n        }else{\r\n            galaxyRes.data[i].isFollowed=0;\r\n        }\r\n        galaxyRes.data[i].putAll(GeoUtil.reverseGeocode(galaxyRes.data[i].longitude,galaxyRes.data[i].latitude));\r\n    }\r\n}\r\n\r\nreturn galaxyRes;');
