imeHandle;\r\nimport \'@/post/object\' as postHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"name\":name,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\ntimeHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT uniqThetaMerge(ip_sketch_agg_state) AS IP, uniqThetaMerge(domain_sketch_agg_state) AS Domain FROM metric_tag WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND tag = \'${name}\'\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1TagTrafficEntityStatistics\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(res);\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n    if(result.data.length > 0){\r\n        var data = {};\r\n        data.result = [];\r\n        for (k,v in result.data[0]) {\r\n            var map = {};\r\n            map.type=k;\r\n            map.count=v.asInt();\r\n            data.result.add(map);\r\n        }\r\n        result.data = data;\r\n    }\r\n}\r\n\r\nreturn result;');
