.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport net.geedge.common.utils.R as R;\r\nimport \'@/public/toHump\' as toHump;\r\nimport \'@/pre/timeHandleNone\' as timeHandle;\r\nimport \'@/post/table\' as postHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"name\":name,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\ntimeHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(stat_time),\'PT${step}S\',\'zero\') AS stat_time, uniqThetaMerge(ip_sketch_agg_state) AS ip_count, uniqThetaMerge(domain_sketch_agg_state) AS domain_count FROM metric_tag WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND  tag = \'${name}\' GROUP BY stat_time ORDER BY stat_time ASC\\\",\\r\\n    \\\"option\\\": \\\"real_time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1TagTrafficEntityTrend\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar result = postGalaxyResult(res);\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n    var o={};\r\n    o.resultType=\"table\";\r\n 	o.result=result.data;\r\n    if(o.result.length > 0){\r\n        for(i,j in o.result){\r\n            var pojo = j;\r\n            var tempObj= {};\r\n            for (key,value in pojo){\r\n                var tempKey = toHump(key);\r\n                tempObj[tempKey] = value.asInt();\r\n            }\r\n            o.result[i] = tempObj;\r\n        }\r\n    }\r\n    result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}\r\n\r\nreturn result;');
