INSERT INTO `magic_api_file` VALUES ('/function/public/order参数处理.ms', '{\n  \"properties\" : { },\n  \"id\" : \"681ff35d05c448ebb1f51bace316b8e1\",\n  \"script\" : null,\n  \"groupId\" : \"673ae6470fae40f2af520bff187a0f96\",\n  \"name\" : \"order参数处理\",\n  \"createTime\" : null,\n  \"updateTime\" : 1673590626762,\n  \"lock\" : null,\n  \"createBy\" : null,\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/orderHandle\",\n  \"description\" : null,\n  \"returnType\" : null,\n  \"mappingPath\" : null,\n  \"parameters\" : [ {\n    \"name\" : \"parameter\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ]\n}\r\n================================\r\nif (parameter == null) {\r\n    return null;\r\n}\r\nvar regx = /[A-Z]/;\r\nMatcher matcher = regx.matcher(parameter);\r\nwhile(matcher.find()){\r\n    String w = matcher.group().trim();\r\n    parameter = parameter.replace(w,\"_\"+w).toLowerCase();\r\n}\r\nreturn parameter');
INSERT INTO `magic_api_file` VALUES ('/function/public/where参数处理.ms', '{\n  \"properties\" : { },\n  \"id\" : \"a76aad7dcb4747359aa69ec716686fc8\",\n  \"script\" : null,\n  \"groupId\" : \"673ae6470fae40f2af520bff187a0f96\",\n  \"name\" : \"where参数处理\",\n  \"createTime\" : null,\n  \"updateTime\" : 1672971712017,\n  \"lock\" : null,\n  \"createBy\" : null,\n  \"updateBy\" : \"admin\",\n  \"path\" : \"/whereHandle\",\n  \"description\" : null,\n  \"returnType\" : null,\n  \"mappingPath\" : null,\n  \"parameters\" : [ {\n    \"name\" : \"parameter\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ]\n}\r\n================================\r\nif(!is_null(parameter.where) && parameter.where != \'\'){\r\n	var data = JSON.parse(parameter.where);\r\n  	var str =\'\';\r\n  	for( key in data){\r\n      	str += \"and \"+key+\"=\"+\"\'\"+data[key]+\"\'\"\r\n    }\r\n        str = str.replace(/Unknown/i,\"\")\r\n  	parameter.where =str;\r\n}\r\nreturn parameter');
INSERT INTO `magic_api_file` VALUES ('/function/public/下划线转驼峰.ms', '{\n  \"properties\" : { },\n  \"id\" : \"ebd85ed2690148878564f108df6708c6\",\n  \"script\" : null,\n  \"groupId\" : \"673ae6470fae40f2af520bff187a0f96\",\n  \"name\" : \"下划线转驼峰\",\n  \"createTime\" : 1672897818981,\n  \"updateTime\" : 1673494954473,\n  \"lock\" : null,\n  \"createBy\" : \"admin\",\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/toHump\",\n  \"description\" : null,\n  \"returnType\" : null,\n  \"mappingPath\" : null,\n  \"parameters\" : [ {\n    \"name\" : \"name\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : \"java.lang.String\",\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ]\n}\r\n================================\r\nif (name == null) {\r\n    return null;\r\n}\r\nvar regx = /_\\w/;\r\nMatcher matcher = regx.matcher(name);\r\nwhile(matcher.find()){\r\n    String w = matcher.group().trim();\r\n    name = name.replace(w,w.toUpperCase().replace(\"_\", \"\"));\r\n}\r\nreturn name\r\n');
INSERT INTO `magic_api_file` VALUES ('/function/public/发送Galaxy请求.ms', '{\n  \"properties\" : { },\n  \"id\" : \"25c0b8a87e5a40d7925cdc222815c1f5\",\n  \"script\" : null,\n  \"groupId\" : \"673ae6470fae40f2af520bff187a0f96\",\n  \"name\" : \"发送Galaxy请求\",\n  \"createTime\" : null,\n  \"updateTime\" : 1703658933490,\n  \"lock\" : null,\n  \"createBy\" : null,\n  \"updateBy\" : \"th\",\n  \"path\" : \"/sendGalaxyRequest\",\n  \"description\" : null,\n  \"returnType\" : null,\n  \"mappingPath\" : null,\n  \"parameters\" : [ {\n    \"name\" : \"url\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : \"java.lang.String\",\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"parameter\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"method\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : \"java.lang.String\",\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ]\n}\r\n================================\r\n/**\r\n * import http;\r\nimport log;\r\nvar config = \"\"\"\r\nselect cvalue from sys_config where ckey = \'galaxy_url\'\r\n\"\"\"\r\nvar json = db.select(config);\r\nSystem.out.print(url)\r\nurl = json.cvalue + url;\r\nvar galaxyResult;\r\nif(method.equals(\"get\")){\r\n    galaxyResult = http.connect(url).param(parameter).get().getBody();\r\n} else if (method.equals(\"post\")) {\r\n    log.info(url);\r\n    log.info(parameter.tagName)\r\n    galaxyResult = http.connect(url).param(parameter).post().getBody();\r\n}\r\n\r\nreturn galaxyResult\r\n**/\r\n\r\n//已废弃');
INSERT INTO `magic_api_file` VALUES ('/function/public/发送GET请求.ms', '{\n  \"properties\" : { },\n  \"id\" : \"ba882184769c43d38cfc71780c4aa0e8\",\n  \"script\" : null,\n  \"groupId\" : \"673ae6470fae40f2af520bff187a0f96\",\n  \"name\" : \"发送GET请求\",\n  \"createTime\" : null,\n  \"updateTime\" : 1703658906745,\n  \"lock\" : null,\n  \"createBy\" : null,\n  \"updateBy\" : \"th\",\n  \"path\" : \"/getGalaxyResult\",\n  \"description\" : null,\n  \"returnType\" : null,\n  \"mappingPath\" : null,\n  \"parameters\" : [ {\n    \"name\" : \"parameter\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : \"java.lang.Object\",\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ]\n}\r\n================================\r\n/**import http\r\n\r\nvar config = \"\"\"\r\nselect cvalue from sys_config where ckey = \'galaxy_url\'\r\n\"\"\"\r\nvar json = db.select(config);\r\nvar url = json.cvalue+\"sql/\";\r\nSystem.out.println(parameter);\r\nvar httpRequest =http.connect(url).param(parameter);\r\nvar galaxyResult = httpRequest.get().getBody();\r\ngalaxyResult.originalUrl = httpRequest.url;\r\n\r\nreturn galaxyResult**/\r\n\r\n//已废弃');
INSERT INTO `magic_api_file` VALUES ('/function/public/发送POST请求.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"4c766cb0c51c4372bddd02a8f4c96978\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"673ae6470fae40f2af520bff187a0f96\",\r\n  \"name\" : \"发送POST请求\",\r\n  \"createTime\" : 1687939346240,\r\n  \"updateTime\" : 1713259644319,\r\n  \"lock\" : null,\r\n  \"createBy\" : \"ljy\",\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/postGalaxyResult\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"parameter\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nimport http\r\nimport log\r\n\r\nvar config = \"\"\"\r\nselect cvalue from sys_config where ckey = \'galaxy_url\'\r\n\"\"\"\r\nvar json = db.select(config);\r\nvar url = json.cvalue+\"v1/query/sql\";\r\nparameter.statement=parameter.query;\r\nparameter.execution_mode=\"oneshot\";\r\nlog.info(parameter.statement);\r\nvar httpRequest =http.connect(url).body(parameter);\r\nvar galaxyResult = httpRequest.post().getBody();\r\ngalaxyResult.originalUrl = parameter.query;\r\n\r\nreturn galaxyResult');
INSERT INTO `magic_api_file` VALUES ('/function/public/获取分位数.ms', '{\n  \"properties\" : { },\n  \"id\" : \"a8f4fd176b264f87a126ccec2c01b48c\",\n  \"script\" : null,\n  \"groupId\" : \"673ae6470fae40f2af520bff187a0f96\",\n  \"name\" : \"获取分位数\",\n  \"createTime\" : 1672897818983,\n  \"updateTime\" : 1673851116387,\n  \"lock\" : null,\n  \"createBy\" : \"admin\",\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/getPercentile\",\n  \"description\" : null,\n  \"returnType\" : null,\n  \"mappingPath\" : null,\n  \"parameters\" : [ {\n    \"name\" : \"list\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : \"java.util.Collection\",\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"p\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : \"java.lang.Number\",\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ]\n}\r\n================================\r\nvar n = list.length;\r\nlist = list.sort((a, b) => {\r\n	if (a > b) {\r\n        return 1;\r\n    } else if(a==b){\r\n        return 0;\r\n    } else {\r\n		return -1;\r\n	}\r\n});\r\nvar px =  p*(n-1);\r\nvar i = Math.floor(px);\r\nvar g = px - i;\r\nif(g==0){\r\n    return list[i];\r\n}\r\nreturn (1-g)*list[i]+g*list[i+1];\r\n');
